// When completing an OpenID Connect flow, the server returns TWO tokens:

const tokenResponse = {
  // 1. The standard OAuth Access Token (used to hit APIs)
  "access_token": "slkdfjlskdjflksjdflkjsdf",

  // 2. The OpenID Connect ID Token (a JWT containing identity)
  "id_token": "eyJhbGciOiJSUz... (Decodes to JSON below)",

  "expires_in": 3600,
  "token_type": "Bearer"
};

// Decoding the id_token payload reveals standard OIDC claims:
{
  "iss": "https://accounts.google.com", // Who issued it
  "sub": "107691503500061507151",       // Unique User ID
  "email": "user@example.com",
  "name": "John Doe",
  "picture": "https://google.com/pic.jpg"
}
